import React, { Component } from "react";
import "./Contactus.css";
import FormJson from './formid';
import PagesJson from './PagesJson';

// Modal component
class ContactModal extends Component {
    render() {
        const { onClose } = this.props;
        const idform = FormJson.find(item => item.formId === 1);
        const contantform = idform.content;

        return (
            <div className="modal">
                <div className="modal-content">
                    <span className="close" onClick={onClose}>&times;</span>
                    {/* Your contact form JSX here */}
                    {contantform.map((item, index) => (
                        <input key={index} type={item.type} className={item.className} placeholder={item.placeholder} required />
                    ))}
                    <button className="sendbutton">Send</button>
                </div>
            </div>
        );
    }
}

export default class Contactus extends Component {
    state = {
        showModal: false
    };

    toggleModal = () => {
        this.setState(prevState => ({
            showModal: !prevState.showModal
        }));
    };

    render() {
        const page1 = PagesJson.find(item => item.PageName === "Contact US");

        return (
            <div className="contact-containerr">
                <div className="rectangle">
                    <h1>
                        <a href="#" className="contact1" onClick={this.toggleModal}>
                            {page1.PageName}
                        </a>
                    </h1>
                    <p className="foryou">{page1.content}</p>
                </div>
                {this.state.showModal && <ContactModal onClose={this.toggleModal} />}
            </div>
        );
    }
}
